VL = "11_VISUAL_LIBRARY"
PAR = ("Arabic counterpart in the same row is reader prose («يعرض…»، «يفصل…»); the English field is a drawing instruction "
       "('Show…', 'Place…', 'Plot…'). The field renders on the Reading page (dist/en/readings/*/). Rewrite carries the Arabic meaning; no fact added.")
PAR_NR = ("Arabic counterpart is reader prose; English is a design instruction. Field does not render in dist today (0 hits), "
          "but it is the governed description a Design recipient will use. No fact added.")


def W(pid, pri, row, field, old, new, lang, ctype, basis, reason, sem="no", **kw):
    return S(pid, "VISUAL-VOICE", pri, old, new, lang, ctype, basis, reason, sheets=[VL], rows=[(VL, row)], fields=[field],
             down="Regenerate 11_VISUAL_LIBRARY row %d; visual_library.json; page_specs.json; dist %s" % (row, lang.upper()),
             vis="Reader-facing description of the visual", sem=sem, **kw)


